import { useContext } from 'react';
import { styled } from '@mui/material/styles';
import { Switch, FormControlLabel, useMediaQuery } from '@mui/material';
import { SettingsContext } from '../../../context/SettingsContext';

const LanguageSwitch = styled(Switch, {
  shouldForwardProp: (prop) => prop !== '$ismobile',
})(({ theme, $ismobile }) => ({
  width: $ismobile ? 54 : 65,
  height: $ismobile ? 30 : 34,
  padding: $ismobile ? 5 : 7,
  '& .MuiSwitch-switchBase': {
    padding: $ismobile ? 1 : 0,
    transform: $ismobile ? 'translateX(4px)' : 'translateX(6px)',
    '&.Mui-checked': {
      color: '#fff',
      transform: $ismobile ? 'translateX(24px)' : 'translateX(26px)',
      '& .MuiSwitch-thumb:before': {
        backgroundImage: `url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" height="${$ismobile ? '18' : '20'}" width="${$ismobile ? '18' : '20'}" viewBox="0 0 20 20"><text x="3" y="15" font-size="14" fill="${encodeURIComponent(
          '#fff',
        )}">中</text></svg>')`, // 中文图标
      },
      '& + .MuiSwitch-track': {
        opacity: 1,
        backgroundColor: '#8796A5',
      },
    },
  },
  '& .MuiSwitch-thumb': {
    backgroundColor: '#001e3c',
    width: $ismobile ? 26 : 32,
    height: $ismobile ? 26 : 32,
    '&::before': {
      content: "''",
      position: 'absolute',
      width: '100%',
      height: '100%',
      top: 0,
      backgroundRepeat: 'no-repeat',
      backgroundPosition: 'center',
      backgroundImage: `url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" height="${$ismobile ? '18' : '20'}" width="${$ismobile ? '18' : '20'}" viewBox="0 0 20 20"><text x="2" y="15" font-size="14" fill="${encodeURIComponent(
        '#fff',
      )}">En</text></svg>')`, // 英文图标
    },
  },
  '& .MuiSwitch-track': {
    opacity: 1,
    backgroundColor: '#aab4be',
    borderRadius: 20 / 2,
  },
}));

export default function LanguageSwitchComponent() {
  const { language, toggleLanguage } = useContext(SettingsContext);
  const isMobile = useMediaQuery((theme) => theme.breakpoints.down('md')); 

  return (
    <FormControlLabel
      control={
        <LanguageSwitch
          checked={language === 'cn'}
          onChange={toggleLanguage}
          aria-label='Language Switch'
          $ismobile={isMobile}
        />
      }
      aria-label='Language Switch'
      label={isMobile ? (language === 'en' ? 'English' : '中文') : ''}
      sx={{
        '& .MuiFormControlLabel-label': {
          fontSize: isMobile ? '16px' : 'inherit',
        },
        gap: isMobile ? 0.8 : 0,
      }}
    />
  );
}